describe("build-debt-ledger executor", () => {
  it("reproduces the case 01 answer key: gross debt, reconciliation, contractual and release views", () => {
    const ledger = buildDebtLedger(camil());
    expect(ledger.blocked).toBe(false);
    expect(ledger.grossDebt).toBe("5670186");
    expect(ledger.reconciliation.withinTolerance).toBe(true);
    expect(ledger.schedule.matchesGross).toBe(true);
    expect(ledger.netDebtViews.contractual.value).toBe("4228477");
    expect(ledger.netDebtViews.reported.value).toBe("4214377");
    expect(ledger.netDebtViews.release?.differenceToReported).toBe("23");
    expect(ledger.byIndexer.find((entry) => entry.indexer === "IPCA")?.balance).toBe("743955");
    const foreign = ledger.byCurrency.filter((entry) => entry.currency !== "BRL").reduce((sum, entry) => sum + Number(entry.balance), 0);
    expect(foreign).toBe(1102582);
    expect(ledger.schedule.periods[0]?.shareOfGross.startsWith("0.2168")).toBe(true);
  });

  it("names what the base does not support instead of filling it", () => {
    const ledger = buildDebtLedger(camil());
    const loans = ledger.uncoveredTerms.filter((entry) => entry.rowId.startsWith("loan-"));
    expect(loans).toHaveLength(4);
    expect(loans[0]?.missing).toEqual(["spread", "maturity", "guarantee"]);
    expect(ledger.uncoveredTerms.some((entry) => entry.rowId.startsWith("deb-"))).toBe(false);
  });

  it("blocks the ledger when a scale mutation breaks the reconciliation, and says so", () => {
    const mutated = camil();
    mutated.rows[0]!.balance = "1314412000";
    const ledger = buildDebtLedger(mutated);
    expect(ledger.blocked).toBe(true);
    expect(ledger.blockReasons[0]).toMatch(/differs from the balance sheet/);
    expect(ledger.schedule.matchesGross).toBe(false);
  });

  it("is consistent: twenty runs, one output fingerprint, independent of row order", () => {
    const first = buildDebtLedger(camil());
    for (let index = 0; index < 20; index += 1) {
      const shuffled = camil();
      shuffled.rows.reverse();
      expect(buildDebtLedger(shuffled).trace.outputFingerprint).toBe(first.trace.outputFingerprint);
    }
  });
});
import {createHash} from "node:crypto";
import {z} from "zod";

/**
 * A procedure is the single, human-reviewable source of operational knowledge.
 * A compiled skill is an immutable runtime projection of that procedure. Nobody edits the
 * compiled projection directly and no runtime is allowed to invent a peer-to-peer handoff.
 */

export const procedureCompilerVersion = "2026.08.25-v2";

/**
 * The ladder a method climbs. Nothing skips a rung: `implemented` needs executable evidence,
 * `ai_reviewed` needs a recorded independent review by a model that went back to the sources,
 * `tested` needs the gold, adversarial and consistency runs, `ready_for_founder` is the hand-off
 * to the founder's integrated evaluation, and `production` needs the founder's approval.
 */
export const procedureMaturitySchema = z.enum(["draft", "candidate", "implemented", "ai_reviewed", "tested", "ready_for_founder", "production"]);
