 66	const d = (value: Decimal.Value) => new Decimal(value);
 67	const out = (value: Decimal) => value.toDecimalPlaces(8).toFixed();
 68	const share = (part: Decimal, whole: Decimal) => (whole.isZero() ? "0" : out(part.div(whole)));
 69	const fingerprint = (value: unknown) => createHash("sha256").update(JSON.stringify(value)).digest("hex");
