 71	export function buildDebtLedger(raw: DebtLedgerInput): DebtLedgerOutput {
 72	  const input = debtLedgerInputSchema.parse(raw);
 73	  const rows = [...input.rows].sort((a, b) => a.id.localeCompare(b.id));
 74	  const gross = rows.reduce((sum, row) => sum.plus(row.balance), d(0));
 75	  const balanceSheetTotal = d(input.balanceSheet.current).plus(input.balanceSheet.nonCurrent);
 76	  const difference = gross.minus(balanceSheetTotal);
 77	  const withinTolerance = difference.abs().lte(input.tolerance);
 78	  const scheduleTotal = input.schedule.reduce((sum, period) => sum.plus(period.amount), d(0));
 79	  const matchesGross = scheduleTotal.eq(gross);
 80	
 81	  const blockReasons: string[] = [];
 82	  if (!withinTolerance) blockReasons.push(`ledger total ${out(gross)} differs from the balance sheet ${out(balanceSheetTotal)} by ${out(difference)}, above the tolerance ${input.tolerance}`);
 83	  if (!matchesGross) blockReasons.push(`schedule total ${out(scheduleTotal)} differs from the ledger total ${out(gross)}`);
 84	
 85	  const cash = d(input.cash.cashAndEquivalents);
 86	  const investments = d(input.cash.financialInvestments);
 87	  const derivativeAssets = d(input.cash.derivativeAssets);
 88	  const derivativeLiabilities = d(input.cash.derivativeLiabilities);
 89	  const reported = gross.minus(cash).minus(investments);
 90	  const contractual = gross.plus(derivativeLiabilities).minus(derivativeAssets).minus(cash).minus(investments);
 91	
 92	  const group = (key: (row: (typeof rows)[number]) => string) => {
 93	    const map = new Map<string, {balance: Decimal; rows: string[]}>();
 94	    for (const row of rows) {
 95	      if (row.contra) continue;
 96	      const entry = map.get(key(row)) ?? {balance: d(0), rows: []};
 97	      entry.balance = entry.balance.plus(row.balance);
 98	      entry.rows.push(row.id);
 99	      map.set(key(row), entry);
100	    }
101	    return [...map.entries()].sort(([a], [b]) => a.localeCompare(b)).map(([label, entry]) => ({label, balance: out(entry.balance), shareOfGross: share(entry.balance, gross), rows: entry.rows}));
102	  };
103	
104	  const uncoveredTerms = rows.filter((row) => !row.contra).map((row) => {
105	    const missing: string[] = [];
106	    if (row.indexer === "unknown") missing.push("indexer");
107	    if (row.spread === undefined || row.spread === null) missing.push("spread");
108	    if (!row.maturity) missing.push("maturity");
109	    if (row.guarantee === undefined || row.guarantee === null) missing.push("guarantee");
110	    return {rowId: row.id, missing};
111	  }).filter((entry) => entry.missing.length > 0);
112	
113	  const body = {
114	    schemaVersion: "method.build-debt-ledger.v1" as const,
115	    referenceDate: input.referenceDate,
116	    unit: input.unit,
117	    blocked: blockReasons.length > 0,
118	    blockReasons,
119	    ledgerRows: rows.map((row) => ({
120	      id: row.id, instrument: row.instrument, series: row.series ?? null, balance: out(d(row.balance)), currency: row.currency, indexer: row.indexer,
121	      spread: row.spread ?? null, maturity: row.maturity ?? null, guarantee: row.guarantee ?? null, lender: row.lender ?? null, contra: row.contra, anchor: row.anchor,
122	    })),
123	    grossDebt: out(gross),
124	    reconciliation: {balanceSheetTotal: out(balanceSheetTotal), difference: out(difference), tolerance: input.tolerance, withinTolerance, anchor: input.balanceSheet.anchor},
125	    schedule: {periods: input.schedule.map((period) => ({period: period.period, amount: out(d(period.amount)), shareOfGross: share(d(period.amount), gross)})), total: out(scheduleTotal), matchesGross, anchor: input.scheduleAnchor},
126	    netDebtViews: {
127	      reported: {value: out(reported), definition: "gross debt minus cash and equivalents minus financial investments (release view)", components: {grossDebt: out(gross), cashAndEquivalents: out(cash), financialInvestments: out(investments)}},
128	      contractual: {value: out(contractual), definition: "gross debt plus derivative liabilities minus derivative assets minus cash and equivalents minus financial investments (indenture definition)", components: {grossDebt: out(gross), derivativeLiabilities: out(derivativeLiabilities), derivativeAssets: out(derivativeAssets), cashAndEquivalents: out(cash), financialInvestments: out(investments)}},
129	      release: input.releaseNetDebt ? {value: out(d(input.releaseNetDebt.value)), differenceToReported: out(d(input.releaseNetDebt.value).minus(reported)), anchor: input.releaseNetDebt.anchor} : null,
130	    },
131	    byIndexer: group((row) => row.indexer).map(({label, ...rest}) => ({indexer: label, ...rest})),
132	    byCurrency: group((row) => row.currency).map(({label, ...rest}) => ({currency: label, ...rest})),
133	    uncoveredTerms,
134	  };
135	  const calculations = ["financial.debt_ledger_balance", "financial.debt_views", "financial.maturity_buckets", "financial.debt_grouping"];
136	  const inputFingerprint = fingerprint(input);
137	  return {...body, trace: {calculations, inputFingerprint, outputFingerprint: fingerprint(body)}};
138	}
